//! Small public in-process cold/warm preparation target, no daemon or GUI.
//! This authenticates actual source/Q preparation, not private Kind12 reporting.
#[path="../../../shared/test_scratch.rs"]mod scratch;
#[path="../../../../analyze/fixtures/report_configuration.rs"]mod report_configuration;
use dmbc::{policy_request::{AnalysisContext,PolicyInputRequest,WorkspacePolicyRequest,WorkspaceAuxiliaryQuestion as Q},request::{BuildRequest,BuildOutcome,Command},runner_host::BuildHost};
use std::path::{Path,PathBuf};
fn put(root:&Path,relative:&str,bytes:impl AsRef<[u8]>){let path=root.join(relative);std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,bytes).unwrap();}
fn fixture(label:&str)->PathBuf{let root=scratch::dir(label);put(&root,"deepquarry.dme","#include \"code/probe.dm\"\n");put(&root,"code/probe.dm","/datum/probe\n    var/value\n/datum/probe/draw()\n    return value\n");put(&root,"code/_generated/reads.dm","// actual stale raw generated state\n");put(&root,"tools/ci/lint_scopes.toml",report_configuration::with_overlay(""));root}
fn request(root:&Path)->BuildRequest{let Command::Build(request)=dmbc::cli::parse(&["prepare-query".into(),root.join("deepquarry.dme").to_string_lossy().into_owned()]).unwrap()else{panic!("actual public PrepareQuery")};let mut request=*request;request.no_cache=true;request.exact_inputs=true;request.progress_enabled=false;request.workers=1;request.timeout_seconds=Some(60);request.engine_template=None;request.bootstrap_catalog=false;request.cache_root=Some(root.join("cache"));request.policy_inputs=Some(PolicyInputRequest{analysis_context:Some(AnalysisContext::OriginalAnalyze0290),workspace:Some(WorkspacePolicyRequest{root:root.to_owned(),recursive_roots:vec![root.join("code")],configuration:root.join("tools/ci/lint_scopes.toml")}),workspace_auxiliary:vec![Q::DerivedReads],..Default::default()});request}
#[derive(Debug,Eq,PartialEq)]struct Revisions{semantic:String,source:String,policy:String}
fn prepare(host:&mut BuildHost,request:&BuildRequest)->Revisions{let outcome=dmbc::request_runner::run_build_with_host(request.clone(),host).unwrap();let BuildOutcome::QueryPrepared{semantic_revision,source_revision,policy_revision:Some(policy_revision),retained:true}=outcome else{panic!("Derived cannot substitute a raw/partial/empty model: {outcome:?}")};assert!(host.declaration_retention_stats().is_some());assert!(host.symbolic_retention_stats().is_none_or(|stats|stats.records==0&&stats.successful_admissions==0&&stats.successful_reuses==0),"analysis must not lower executable code");assert!(!request.project.with_extension("dmb").exists());assert!(!request.project.with_extension("rsc").exists());Revisions{semantic:semantic_revision,source:source_revision,policy:policy_revision}}
#[test]fn actual_public_derived_cold_then_warm_preserves_current_source_and_reissues_for_uncompiled_raw_edits(){let root=fixture("public-derived-cold-warm");let request=request(&root);let mut host=BuildHost::default();let cold=prepare(&mut host,&request);assert_eq!(prepare(&mut host,&request),cold);put(&root,"code/uncompiled.dm","/datum/uncompiled\n    var/missing\n/datum/uncompiled/draw()\n    return missing\n");let added=prepare(&mut host,&request);assert_eq!(added.source,cold.source,"uncompiled CODE leaves the frontend source pin unchanged");assert_ne!(added.policy,cold.policy,"all raw CODE discovery belongs to the policy even when DME does not compile the file");std::fs::remove_file(root.join("code/uncompiled.dm")).unwrap();let removed=prepare(&mut host,&request);assert_ne!(removed.policy,added.policy);prepare(&mut host,&request);}
#[test]fn actual_public_derived_bad_configuration_precedes_unreadable_manifest_then_fresh_scope_recovers(){let root=fixture("public-derived-config-first");let request=request(&root);let mut host=BuildHost::default();std::fs::remove_file(&request.project).unwrap();std::fs::create_dir(&request.project).unwrap();put(&root,"tools/ci/lint_scopes.toml","[not valid TOML");let error=dmbc::request_runner::run_build_with_host(request.clone(),&mut host).unwrap_err();let text=error.to_string();assert!(text.contains("TOML")||text.contains("toml"),"actual config failure must precede model IO: {text}");std::fs::remove_dir(&request.project).unwrap();put(&root,"deepquarry.dme","#include \"code/probe.dm\"\n");put(&root,"tools/ci/lint_scopes.toml",report_configuration::with_overlay(""));prepare(&mut host,&request);}
#[test]fn actual_public_derived_context_and_role_are_not_interchangeable_and_bom_raw_bytes_rebind(){let root=fixture("public-derived-context-bom");let request=request(&root);let mut host=BuildHost::default();let first=prepare(&mut host,&request);let mut wrong=request.clone();wrong.policy_inputs.as_mut().unwrap().analysis_context=None;assert!(dmbc::request_runner::run_build_with_host(wrong,&mut host).is_err());put(&root,"code/probe.dm",b"\xef\xbb\xbf/datum/probe\n    var/value\n/datum/probe/draw()\n    return value\n");let bom=prepare(&mut host,&request);assert_eq!(first.source,bom.source,"BOM leaves the decoded frontend pin unchanged");assert_ne!(first.policy,bom.policy,"the policy pin must distinguish genuine BOM bytes from the same decoded view");assert_eq!(prepare(&mut host,&request),bom);}
